def search(nums, target):
    l, r = 0, len(nums) - 1
    while l <= r:
        m = (l + r) // 2
        if nums[m] == target:
            return m
        elif nums[m] < target:
            l = m + 1
        else:
            r = m - 1
    return -1


def main():
    nums = list(map(int, input().split()))
    target = int(input())
    print(search(nums, target))


if __name__ == "__main__":
    main()

def lower_bound(nums, target):
    """返回第一个 >= target 的下标；若全部小于 target 则返回 len(nums)。"""
    l, r = 0, len(nums)
    while l < r:
        m = (l + r) // 2
        if nums[m] < target:
            l = m + 1
        else:
            r = m
    return l


def search(nums, target):
    i = lower_bound(nums, target)
    if i < len(nums) and nums[i] == target:
        return i
    return -1


def main():
    nums = list(map(int, input().split()))
    target = int(input())
    print(search(nums, target))


if __name__ == "__main__":
    main()
